// Función para generar SKU único
function generateSKU(index: number): string {
  return `SKU-${String(index).padStart(5, '0')}`;
}

// Exportar productos con ID y SKU completos
export const fullProducts: Product[] = productDatabase.map((p, index) => ({
  ...p,
  id: `prod-${String(index + 1).padStart(3, '0')}`,
  sku: p.sku || generateSKU(index + 1),
  description: p.description || p.name,
  image: getProductImage(p.name || ""),
  isActive: true,
  createdAt: new Date(),
  updatedAt: new Date(),
})) as Product[];
